/**
 * Everything the host decides about the node. Paths must be absolute.
 */
public struct NodeSettings: Equatable, Hashable {
    /**
     * Contract, delegate and secret stores live below this directory.
     */
    public var dataDir: String
    /**
     * The node's persisted `config.toml` lives below this directory.
     */
    public var configDir: String
    /**
     * Log files go here.
     */
    public var logDir: String
    /**
     * Unpacked web apps go here. Defaults to a folder in `data_dir`.
     */
    public var cacheDir: String?
    public var mode: NodeMode
    /**
     * Try this loopback port first for the client API, so web storage keeps
     * the same origin across launches. Any free port is used when it is taken.
     */
    public var preferredWsPort: UInt16?
    /**
     * UDP port for peer traffic. Any free port when unset.
     */
    public var networkPort: UInt16?
    /**
     * Gateways to join through. Empty in network mode means the public
     * gateway index.
     */
    public var gateways: [GatewayOverride]
    /**
     * Wasm backend. The target's default when unset.
     */
    public var wasmBackend: WasmBackendChoice?
    /**
     * A `tracing` filter such as `info` or `info,freenet=debug`.
     */
    public var logFilter: String?
    /**
     * Byte budget for compiled contract modules. 64 MiB when unset.
     */
    public var moduleCacheBudgetBytes: UInt64?
    /**
     * Byte budget for hosted contract state. 128 MiB when unset.
     */
    public var maxHostingStorageBytes: UInt64?
    /**
     * Disk budget for everything the node stores. 1 GiB when unset.
     */
    public var maxHostingDiskBytes: UInt64?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Contract, delegate and secret stores live below this directory.
         */dataDir: String, 
        /**
         * The node's persisted `config.toml` lives below this directory.
         */configDir: String, 
        /**
         * Log files go here.
         */logDir: String, 
        /**
         * Unpacked web apps go here. Defaults to a folder in `data_dir`.
         */cacheDir: String? = nil, mode: NodeMode, 
        /**
         * Try this loopback port first for the client API, so web storage keeps
         * the same origin across launches. Any free port is used when it is taken.
         */preferredWsPort: UInt16? = nil, 
        /**
         * UDP port for peer traffic. Any free port when unset.
         */networkPort: UInt16? = nil, 
        /**
         * Gateways to join through. Empty in network mode means the public
         * gateway index.
         */gateways: [GatewayOverride] = [], 
        /**
         * Wasm backend. The target's default when unset.
         */wasmBackend: WasmBackendChoice? = nil, 
        /**
         * A `tracing` filter such as `info` or `info,freenet=debug`.
         */logFilter: String? = nil, 
        /**
         * Byte budget for compiled contract modules. 64 MiB when unset.
         */moduleCacheBudgetBytes: UInt64? = nil, 
        /**
         * Byte budget for hosted contract state. 128 MiB when unset.
         */maxHostingStorageBytes: UInt64? = nil, 
        /**
         * Disk budget for everything the node stores. 1 GiB when unset.
         */maxHostingDiskBytes: UInt64? = nil) {
        self.dataDir = dataDir
        self.configDir = configDir
        self.logDir = logDir
        self.cacheDir = cacheDir
        self.mode = mode
        self.preferredWsPort = preferredWsPort
        self.networkPort = networkPort
        self.gateways = gateways
        self.wasmBackend = wasmBackend
        self.logFilter = logFilter
        self.moduleCacheBudgetBytes = moduleCacheBudgetBytes
        self.maxHostingStorageBytes = maxHostingStorageBytes
        self.maxHostingDiskBytes = maxHostingDiskBytes
    }

    

    
}

