/**
 * What kind of failure a client request met. Each platform maps the same
 * node reply to the same kind, which the protocol fixtures check.
 */

public enum ClientErrorKind: Equatable, Hashable {
    
    /**
     * The network holds no copy of the contract.
     */
    case notFound
    /**
     * The node has no code for the contract, so it cannot run it.
     */
    case missingContract
    /**
     * The contract rejected the request, for example an invalid update.
     */
    case contractRejected
    /**
     * A delegate call failed.
     */
    case delegateError
    /**
     * No reply arrived within the request's time limit. The outcome is
     * uncertain: the node may still apply the request.
     */
    case timeout
    /**
     * The connection to the node closed.
     */
    case disconnected
    /**
     * The node is not reachable or is shutting down.
     */
    case nodeUnavailable
    /**
     * The node has no peers yet, so it cannot reach the network.
     */
    case noPeers
    /**
     * A reply could not be decoded.
     */
    case deserialization
    /**
     * The node reported that the operation failed.
     */
    case operationFailed
    /**
     * Anything else, with the node's message.
     */
    case other





}

#if compiler(>=6)
extension ClientErrorKind: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeClientErrorKind: FfiConverterRustBuffer {
    typealias SwiftType = ClientErrorKind

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ClientErrorKind {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .notFound
        
        case 2: return .missingContract
        
        case 3: return .contractRejected
        
        case 4: return .delegateError
        
        case 5: return .timeout
        
        case 6: return .disconnected
        
        case 7: return .nodeUnavailable
        
        case 8: return .noPeers
        
        case 9: return .deserialization
        
        case 10: return .operationFailed
        
        case 11: return .other
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ClientErrorKind, into buf: inout [UInt8]) {
        switch value {
        
        
        case .notFound:
            writeInt(&buf, Int32(1))
        
        
        case .missingContract:
            writeInt(&buf, Int32(2))
        
        
        case .contractRejected:
            writeInt(&buf, Int32(3))
        
        
        case .delegateError:
            writeInt(&buf, Int32(4))
        
        
        case .timeout:
            writeInt(&buf, Int32(5))
        
        
        case .disconnected:
            writeInt(&buf, Int32(6))
        
        
        case .nodeUnavailable:
            writeInt(&buf, Int32(7))
        
        
        case .noPeers:
            writeInt(&buf, Int32(8))
        
        
        case .deserialization:
            writeInt(&buf, Int32(9))
        
        
        case .operationFailed:
            writeInt(&buf, Int32(10))
        
        
        case .other:
            writeInt(&buf, Int32(11))
        
        }
    }
}


