public struct FfiConverterTypeMobileError: FfiConverterRustBuffer {
    typealias SwiftType = MobileError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> MobileError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidSettings(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Storage(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 3: return .NotRunning
        case 4: return .StartFailed(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 5: return .NoGateways(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Timeout(
            what: try FfiConverterString.read(from: &buf)
            )
        case 7: return .Client(
            kind: try FfiConverterTypeClientErrorKind.read(from: &buf), 
            detail: try FfiConverterString.read(from: &buf)
            )
        case 8: return .Bundle(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 9: return .BackendUnavailable(
            backend: try FfiConverterString.read(from: &buf)
            )
        case 10: return .Internal(
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: MobileError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidSettings(reason):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Storage(reason):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .NotRunning:
            writeInt(&buf, Int32(3))
        
        
        case let .StartFailed(reason):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .NoGateways(reason):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Timeout(what):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(what, into: &buf)
            
        
        case let .Client(kind,detail):
            writeInt(&buf, Int32(7))
            FfiConverterTypeClientErrorKind.write(kind, into: &buf)
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Bundle(reason):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .BackendUnavailable(backend):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(backend, into: &buf)
            
        
        case let .Internal(reason):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


